insert into news (date, title_ku, title_tr, title_en, title_ru, body_ku, body_tr, body_en, body_ru, image_url, link_url) values ('2026-10-29', 'Konserên Sermawezê: Rûsya, Fransa, Almanya', 'Kasım konserleri: Rusya, Fransa, Almanya', 'November concerts: Russia, France, Germany', 'Ноябрьские концерты: Россия, Франция, Германия', 'Azad Bedran di Sermawezê de li çar bajaran derdikeve ser sahneyê: 15ê Sermawezê li Sankt Petersburgê, 27ê li Parîsê, 28ê li Reimsê û 29ê li Kielê. Konsera Sankt Petersburgê li Restoran „Skazka Vostoka – 1001 Noç“ (Lesnoy prospekt 48) ye, deriyên salonê saet 19:00an vedibin; ji bo cih rezervekirinê: +7 981 717-60-62 an +7 812 295-31-05. Cih û bilêtên Parîs, Reims û Kielê dê di demeke nêzîk de werin ragihandin.', 'Azad Bedran kasımda dört şehirde sahnede: 15 Kasım St. Petersburg, 27 Kasım Paris, 28 Kasım Reims ve 29 Kasım Kiel. St. Petersburg konseri Restoran „Skazka Vostoka – 1001 Noç“ta (Lesnoy prospekt 48); kapılar 19:00’da açılıyor, rezervasyon: +7 981 717-60-62 veya +7 812 295-31-05. Paris, Reims ve Kiel için mekân ve bilet bilgileri yakında duyurulacak.', 'Azad Bedran plays four cities in November: St. Petersburg on 15 November, Paris on the 27th, Reims on the 28th and Kiel on the 29th. The St. Petersburg show is at Restaurant “Skazka Vostoka – 1001 Nights” (Lesnoy prospekt 48), doors at 7 pm, reservations on +7 981 717-60-62 or +7 812 295-31-05. Venues and tickets for Paris, Reims and Kiel will be announced soon.', 'В ноябре Азад Бедран выступит в четырёх городах: 15 ноября в Санкт-Петербурге, 27-го в Париже, 28-го в Реймсе и 29-го в Киле. Концерт в Санкт-Петербурге пройдёт в ресторане «Сказка Востока 1001 Ночь» (Лесной проспект, 48), сбор гостей в 19:00, бронирование столов: +7 981 717-60-62 или +7 812 295-31-05. Площадки и билеты в Париже, Реймсе и Киле будут объявлены в ближайшее время.', '/images/poster-kasim-2026.jpg', null);
insert into news (date, title_ku, title_tr, title_en, title_ru, body_ku, body_tr, body_en, body_ru, image_url, link_url) values ('2026-10-08', 'Single ya nû: “Ez Dînim”', 'Yeni single: “Ez Dînim”', 'New single: “Ez Dînim”', 'Новый сингл «Ez Dînim»', 'Strana nû ya Azad Bedran “Ez Dînim” ji 8ê Kewçêra 2026an ve li ser hemû platformên muzîkê ye. Li vir guhdarî bike û platforma xwe hilbijêre.', 'Azad Bedran’ın yeni şarkısı “Ez Dînim” 8 Ekim 2026’dan beri tüm dijital platformlarda. Buradan dinleyebilir, platformunu seçebilirsin.', 'Azad Bedran’s new single “Ez Dînim” has been out on every streaming platform since 8 October 2026. Listen here and pick your platform.', 'Новый сингл Азада Бедрана «Ez Dînim» доступен на всех стриминговых платформах с 8 октября 2026 года. Слушайте здесь и выбирайте свою платформу.', 'https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/14/1a/7a/141a7adc-6a72-b5e9-5963-83662ed966a6/artwork.jpg/1000x1000bb.jpg', null);
insert into news (date, title_ku, title_tr, title_en, title_ru, body_ku, body_tr, body_en, body_ru, image_url, link_url) values ('2026-09-24', 'Bi Suleyman re: “Tu Çîrokek Bê Hempa”', 'Suleyman ile: “Tu Çîrokek Bê Hempa”', 'With Suleyman: “Tu Çîrokek Bê Hempa”', 'С Сулейманом: «Tu Çîrokek Bê Hempa»', 'Azad Bedran û Suleyman strana hevpar “Tu Çîrokek Bê Hempa” di 24ê Rezbera 2026an de weşandin.', 'Azad Bedran ve Suleyman’ın birlikte seslendirdiği “Tu Çîrokek Bê Hempa” 24 Eylül 2026’da yayımlandı.', 'Azad Bedran and Suleyman released their joint single “Tu Çîrokek Bê Hempa” on 24 September 2026.', 'Азад Бедран и Сулейман выпустили совместный сингл «Tu Çîrokek Bê Hempa» 24 сентября 2026 года.', 'https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/76/c3/62/76c3628a-f6ff-0843-650f-a132bd0931e6/artwork.jpg/1000x1000bb.jpg', null);
insert into news (date, title_ku, title_tr, title_en, title_ru, body_ku, body_tr, body_en, body_ru, image_url, link_url) values ('2026-07-31', 'Albûma zindî: “Evîna Azad (Live)”', 'Canlı albüm: “Evîna Azad (Live)”', 'Live album: “Evîna Azad (Live)”', 'Концертный альбом «Evîna Azad (Live)»', '13 stran, bi enerjiya sahneyê: albûma zindî “Evîna Azad (Live)” di 31ê Tîrmeha 2026an de derket – di nav de “Zindan” jî heye, strana wî ya herî naskirî.', 'Sahnenin enerjisiyle 13 şarkı: canlı albüm “Evîna Azad (Live)” 31 Temmuz 2026’da çıktı – aralarında en bilinen şarkısı “Zindan” da var.', 'Thirteen songs with the energy of the stage: the live album “Evîna Azad (Live)” came out on 31 July 2026, including “Zindan”, his best-known song.', 'Тринадцать песен с энергией сцены: концертный альбом «Evîna Azad (Live)» вышел 31 июля 2026 года – в том числе «Zindan», его самая известная песня.', 'https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/33/ed/4c/33ed4cd1-1a2c-babb-770a-113d900bf9a5/cover.jpg/1000x1000bb.jpg', null);
insert into news (date, title_ku, title_tr, title_en, title_ru, body_ku, body_tr, body_en, body_ru, image_url, link_url) values ('2026-03-26', 'Ji bo Amedsporê: “Amedspor Geliyor”', 'Amedspor için: “Amedspor Geliyor”', 'For Amedspor: “Amedspor Geliyor”', 'Для «Амедспора»: «Amedspor Geliyor»', 'Piştî “Aşk Amedspor”, Azad Bedran di 26ê Adara 2026an de strana nû “Amedspor Geliyor” ji bo tîma Amedê weşand.', '“Aşk Amedspor”un ardından Azad Bedran, 26 Mart 2026’da Amed takımı için yeni şarkısı “Amedspor Geliyor”u yayımladı.', 'Following “Aşk Amedspor”, Azad Bedran released a new anthem for the Amed club, “Amedspor Geliyor”, on 26 March 2026.', 'Вслед за «Aşk Amedspor» Азад Бедран 26 марта 2026 года выпустил новый гимн для клуба из Амеда – «Amedspor Geliyor».', 'https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/23/7f/e5/237fe520-49e6-3dd3-d5dd-abc61512280a/cover.jpg/1000x1000bb.jpg', null);
